const WORD_PATTERN = /([A-Za-z]+(?:['’-][A-Za-z]+)*)/g;

export interface ReaderTextToken {
  value: string;
  isWord: boolean;
}

/** 带上下标的切词结果，下标是相对于传入字符串的字符位置。 */
export interface ReaderTextTokenRange extends ReaderTextToken {
  start: number;
  end: number;
}

export function tokenizeReaderText(value: string): ReaderTextToken[] {
  return value
    .split(WORD_PATTERN)
    .filter(Boolean)
    .map((token) => ({
      value: token,
      isWord: /^[A-Za-z]/.test(token),
    }));
}

/**
 * 给标注用的切词：每个 token 附带自己在原文里的区间。
 * 切分不会丢字符，token 首尾相接正好拼回原字符串。
 */
export function tokenizeReaderTextWithOffsets(
  value: string,
): ReaderTextTokenRange[] {
  let cursor = 0;
  return tokenizeReaderText(value).map((token) => {
    const start = cursor;
    cursor += token.value.length;
    return { ...token, start, end: cursor };
  });
}

export function normalizeReaderWord(value: string) {
  const normalized = value
    .replaceAll("’", "'")
    .toLowerCase()
    .replace(/[^a-z'-]/g, "");

  return normalized.endsWith("'s")
    ? normalized.slice(0, -2)
    : normalized;
}
